\section{Proof of Proposition 1}\label{app:proof1}
The radiation pattern can be expressed as the integral of the radiations from all points within the antenna aperture. Setting the center of the smallest circle enclosing the antenna aperture as the origin, let
$\boldsymbol p= [r\cos\phi,r\sin\phi]^{\rm T}$ denote a point in the aperture and let $\boldsymbol x =[\cos\theta,\sin\theta]^{\rm T}$
denote the observation direction. Therefore, we have
\begin{align}\label{Radiation}
	f(\theta)
	&=
	\int_{\mathcal A}
	W(\boldsymbol p)
	e^{j\frac{2\pi}{\lambda}
		\boldsymbol p^{\rm T}\boldsymbol x}
	{\rm d}\boldsymbol p \nonumber
	&=
	\int_{\mathcal A}
	W(\boldsymbol p)
	e^{j\frac{2\pi r}{\lambda}
		\cos(\theta-\phi)}
	{\rm d}\boldsymbol p,
\end{align}
where $\mathcal A$ denotes the antenna-aperture region, $r=\|\boldsymbol p\|_2$, and $W(\boldsymbol p)$ is the current intensity at $\boldsymbol p$. Applying the Jacobi-Anger expansion gives~\cite{Gbur2011}
\begin{align}\label{JacobiAnger}
	e^{j\frac{2\pi r}{\lambda}
		\cos(\theta-\phi)}
	=
	\sum_{n=-\infty}^{\infty}
	j^n
	J_n\left(\frac{2\pi r}{\lambda}\right)
	e^{jn\theta}e^{-jn\phi},
\end{align}
where $J_n(\cdot)$ is the first-kind Bessel function .
Substituting \eqref{JacobiAnger} into \eqref{Radiation}, we obtain
\begin{align}
	f(\theta)
	=&
	\int_{\mathcal A}
	W(\boldsymbol p)
	\sum_{n=-\infty}^{\infty}
	j^n
	J_n\left(\frac{2\pi r}{\lambda}\right)
	e^{jn\theta}e^{-jn\phi}
	{\rm d}\boldsymbol p
	\nonumber
	=&
	\sum_{n=-\infty}^{\infty}
	\left[
	j^n
	\int_{\mathcal A}
	W(\boldsymbol p)
	J_n\left(\frac{2\pi r}{\lambda}\right)
	e^{-jn\phi}
	{\rm d}\boldsymbol p
	\right]e^{jn\theta}.
	\label{RadiationFourier}
\end{align}
By comparing \eqref{RadiationFourier} with
\eqref{FourierTransform}, we have
\begin{align}\label{FourierCoefficient}
	\gamma_n
	=
	j^n
	\int_{\mathcal A}
	W(\boldsymbol p)
	J_n\left(\frac{2\pi r}{\lambda}\right)
	e^{-jn\phi}
	{\rm d}\boldsymbol p.
\end{align}
The relationship in \eqref{FourierCoefficient} shows that the
$n$th angular mode is governed by the $n$th-order Bessel function
evaluated over the antenna aperture. We next determine the significant
range of $n$. Define the maximum aperture radius as
\begin{align}
	R_{\mathcal A}
	\triangleq
	\max_{\boldsymbol p \in\mathcal A}~r 
	=
	\max_{\boldsymbol p \in\mathcal A}~
	\|\boldsymbol p\|_2.
\end{align}
Its normalized electrical radius is $2\pi R_{\mathcal A}/\lambda$.
For every point within the antenna aperture, the argument of the
Bessel function satisfies
\begin{align}
	0
	\leq
	\frac{2\pi r}{\lambda}
	\leq
	\frac{2\pi R_{\mathcal A}}{\lambda}.
\end{align}
For an integer $n\geq1$, the Bessel function satisfies~\cite{Olver2010}
\begin{align}
	|J_n(x)|
	\leq
	\frac{1}{n!}\left(\frac{x}{2}\right)^n
	\leq
	\left(\frac{ex}{2n}\right)^n,
	\label{BesselSimpleBound}
\end{align}
where the second inequality follows from
$n!\geq(n/e)^n$. Since
$x\leq2\pi R_{\mathcal A}/\lambda$ over the antenna aperture,
\eqref{BesselSimpleBound} further gives
\begin{align}
	|J_n(x)|
	\leq
	\left(
	\frac{e\pi R_{\mathcal A}}
	{n\lambda}
	\right)^n.
\end{align}
Accordingly, \eqref{FourierCoefficient} implies
\begin{align}\label{gamma_n}
	|\gamma_n|
	\leq
	\left(
	\int_{\mathcal A}|W(\boldsymbol p)|
	{\rm d}\boldsymbol p
	\right)
	\left(
	\frac{e\pi R_{\mathcal A}}
	{n\lambda}
	\right)^n.
\end{align}
When
\begin{align}
	n>\frac{e\pi R_{\rm A}}{\lambda},
\end{align}
${e\pi R_{\mathcal A}}/{(n\lambda)}< 1$, and the second factor on the right-hand side of \eqref{gamma_n} rapidly approaches zero as $n$ increases. For negative orders,
$J_{-n}(x)=(-1)^nJ_n(x)$, and hence the same upper envelope applies
with $n$ replaced by $|n|$. Therefore, a finite antenna aperture induces
a rapidly decaying envelope on sufficiently high-order Fourier coefficients.
This motivates the aperture-dependent effective Fourier truncation order
\begin{align}
	N\triangleq
	\left\lceil\frac{e\pi R_{\rm A}}{\lambda}\right\rceil .
\end{align}


\section{Derivation of $\rho_n$}\label{app:proof2}
From \eqref{FourierCoefficient}, the power of the $n$th Fourier coefficient satisfies
\begin{align}
	|\gamma_n|^2
	&=
	\left|
	\int_{\mathcal A}
	W(\boldsymbol p)
	J_n\left(
	\frac{2\pi r}{\lambda} 
	\right)e^{-jn\phi}
	{\rm d}\boldsymbol p
	\right|^2
	\leq
	P_W B_n,
	\label{GammaCauchyBound}
\end{align}
where the inequality follows from the Cauchy--Schwarz inequality, and
\begin{align}
	P_W
	\!\triangleq\!
	\int_{\mathcal A}|W(\boldsymbol p)|^2{\rm d}\boldsymbol p,\
	B_n
	\!\triangleq\!
	\int_{\mathcal A}
	\left|
	J_n\left(
	\frac{2\pi r}{\lambda}
	\right)
	\right|^2
	{\rm d}\boldsymbol p.
\end{align}
For a given antenna aperture, $B_n$ is a geometry-dependent constant that can be evaluated numerically. Moreover, since
$J_{-n}(x)=(-1)^nJ_n(x)$, we have $B_{-n}=B_n$.
Although the total radiation-pattern power is normalized in
\eqref{CoefficientPowerConstraint}, it does not directly provide a finite upper bound on $P_W$. In particular, weakly radiating or non-radiating current components and destructive current cancellation may produce a large current norm while maintaining the same normalized far-field power. Therefore, obtaining a universal strict upper bound on $P_W$ solely from the radiation-power normalization is generally difficult. To characterize the physically admissible current intensity, we introduce the modeling constraint
\begin{align}\label{CurrentPowerConstraint}
	P_W\leq C,
\end{align}
where $C>0$ is a current-capability parameter. A smaller $C$ represents a more restrictive antenna model with limited current intensity and weaker high-order excitation, whereas a larger $C$ allows stronger and more complex current distributions.  Combining \eqref{GammaCauchyBound} and
\eqref{CurrentPowerConstraint} yields
\begin{align}
	|\gamma_n|^2\leq C B_n.
\end{align}
Meanwhile, the total power constraint
\eqref{CoefficientPowerConstraint} implies
$|\gamma_n|^2\leq1$ for every order. Hence,
\begin{align}\label{IndividualModeBound}
	|\gamma_n|^2
	\leq
	\min\{1,C B_n\}.
\end{align}
