\section{System Model}
\subsection{Signal Model}
We consider vehicular networks in which the BS, equipped with a MIMO uniform linear array (ULA)  consisting of ${N}_{t}$ transmit antennas and $N_r$ receive antennas, serves $K$ user vehicles with high mobility.
We assume that the sensing target is the same as the communication user, and both the communication link and the sensing  path are  line-of-sight (LOS).
Let $n$  denote the index of time slots.
Each time slot has duration $\Delta T$, and at time  $t \in [0,\Delta T)$ within time slot $n$, the ISAC signal transmitted from the BS to the $K$ vehicles is expressed as
${\bf s}_n(t)=[s_{1,n}(t),...,s_{K,n}(t)]^{\sf T}$.
We assume the geometric parameters, i.e., the angle, Doppler frequency, time delay, and distance, remain  quasi-static and change across time slots according to the mobility model.
At the BS, ${\bf s}_n(t)$ is precoded by ${\bf F}_n$ before transmission as
\begin{align}
 {\bf{x}}_{n}(t) = \sqrt{P}{\bf F}_n{\bf s}_n(t),
\end{align}
where ${\bf F}_n = [{\bf f}_{1,n},\cdots,{\bf f}_{K,n}] \in {\mathbb{C}^{N_t\times K}}$ denotes the downlink beamforming matrix,  ${\bf f}_{k,n} \in {\mathbb{C}}^{N_t}$ is the beamformer for vehicle $k$, and ${P}$ is the maximum transmit power.
Let the transmit and receive steering vectors be  ${\bf a}(\theta_{k,n}) = \sqrt{{1}/{N_t}}[1,e^{-j\pi\cos{\theta_{k,n}}}, \cdots, e^{-j\pi(N_t-1)\cos{\theta_{k,n}}}]^{\sf T}$ and ${\bf b}(\theta_{k,n}) = \sqrt{{1}/{N_r}}[1,e^{-j\pi\cos{\theta_{k,n}}}, \cdots, e^{-j\pi(N_r-1)\cos{\theta_{k,n}}}]^{\sf T}$, respectively, where $\theta_{k,n}$ is  the  angle between vehicle $k$ and the BS.
Then, the sensing echo signal vector at the BS reflected from $K$ vehicles in the $n$th time slot \cite{liu2020radar, liu2022learning} is represented as follows:
\begin{align}
 \!{\bf{r}}_n(t)\!=\!\sum_{k=1}^{K} \beta_{k,n}e^{j2\pi\mu_{k,n}t}{\bf b}(\theta_{k,n}){\bf a}^{\sf H}(\!\theta_{k,n}\!){\bf x}_n(t\!-\!\zeta_{k,n})\!+\!{\bf n}(t),
 \label{eq:echo}
\end{align}
where $\beta_{k,n} = \sqrt{N_t N_r}\frac{\phi}{2 d_{k,n}}$ is the reflection coefficient, $d_{k,n}$ is the distance between the BS and  vehicle $k$, $\phi$ is the complex radar cross-section,  $\mu_{k,n}$ is the Doppler frequency, $\zeta_{k,n}$ is the time delay, and ${\bf n}(t) \sim {\mathcal{CN}(0,\sigma^2\bI_{N_r})}$ is the complex additive white Gaussian noise with zero mean and variance  $\sigma^2$.
{We note that clutter from surrounding scatterers is neglected, since dominant
road-side clutter is typically stationary and can be suppressed in the Doppler domain before feature extraction \cite{richards2014fundamentals}.
Extending the proposed framework to account for the residual clutter caused by imperfect suppression and moving non-user scatterers is left as future work.}
By leveraging the massive MIMO system at the BS, the steering vectors corresponding to distinct angles become increasingly separable \cite{marzetta2016fundamentals}, which allows the BS to distinguish individual vehicles based on their angles of arrival and process them independently.
{Accordingly, the echo signal from the $k$th vehicle can be extracted from the aggregate signal in \eqref{eq:echo} by applying a spatial filtering process \cite{van2002optimum,liu2022learning} as
\begin{align}
 \label{eq:rxecho0}
 &e_{k,n}(t) = {\bf b}^{\sf H}({\hat \theta}_{k,n}){\bf  r}_{n}(t)

 \nonumber
 &\approx\beta_{k,n}e^{j2\pi\mu_{k,n}t}{\bf a}^{\sf H}(\theta_{k,n}){\bf x}_n(t-\zeta_{k,n})\!+\!{ n}_{k,n}(t)

 \label{eq:rxecho}
 &+\!\sum_{i\neq k}\!\beta_{i,n}e^{j2\pi\mu_{i,n}t}\big[{\bf b}^{\sf H}\!(\theta_{k,n}){\bf b}(\theta_{i,n})\big]{\bf a}^{\sf H}\!(\theta_{i,n}){\bf x}_n(t\!-\!\zeta_{i,n}),
\end{align}}
where ${\hat \theta}_{k,n}$ denotes an estimate of ${ \theta}_{k,n}$ obtained via angle of arrival estimation \cite{van2002optimum}, and $n_{k,n}(t) = {\bf b}^{\sf H}({\hat \theta}_{k,n}){\bf n}(t)$.
For simplification, we assume that  ${\hat \theta}_{k,n} \approx {\theta}_{k,n}$, and hence,
${\bf b}^{\sf H}({\hat \theta}_{k,n}){\bf b}({\theta}_{k,n}) \approx 1$.
We consider $L$ samples in each time slot.
Then, by aggregating $L$ samples within the time slot, we can obtain
\begin{align}
 \label{eq:ek}
 {\bf e}_{k,n} = [e_{k,n}(1),\cdots,e_{k,n}(L)]^{\sf T} \in {\mathbb{C}}^{L}.
\end{align}
Next, the received signal of vehicle $k$ at time instant $t$ within time slot $n$ can be expressed  as \cite{liu2022learning,zhang2024transformer}
\begin{align}
 &y_{k,n}(t)\!=\!\! \sqrt{P\alpha_{k,n}}e^{j2\pi\mu_{k,n}t}{\bf a}^{\sf H}(\theta_{k,n})\!\!\sum_{i=1}^{K}{\bf f}_{i,n}s_{i,n}(t) \!+\! z_{k,n}(t),
 \label{eq:Received signal}
\end{align}
where $\alpha_{k,n}$ is given by $N_t\alpha_0(d_{k,n}/d_0)^{-\eta}$.
Here, $\alpha_0$ is the path loss at a reference distance $d_0$ and $\eta$ denotes
the path loss exponent.
In addition, $z_{k,n}(t) \sim  {\mathcal{CN}(0,\sigma^2)}$ is the noise of $k$th vehicle with variance $\sigma^2$.
\subsection{Vehicle Mobility}
To support beam prediction under mobility, vehicle motion is described using a kinematic equation \cite{liu2022learning,zhang2024transformer}.
Vehicles are assumed to move parallel to the road with a nearly constant velocity direction within each time slot, and the velocity model is characterized by the velocity magnitude as follows:
\begin{align}
 \label{eq:velocity}
 v_{k,n} = v_{k,n-1}+ \Delta v_{k,n-1},
\end{align}
where $v_{k,n}$ denotes the average velocity magnitude of  vehicle $k$ and $\Delta v_{k,n-1}$ is the velocity increment
within time slot $(n-1)$.
Then, the kinematic equations of angle and distance are expressed as \cite{liu2022learning,zhang2024transformer}
\begin{align*}
 &\sin({\theta_{k,n}-\theta_{k,n-1}}) {d_{k,n}}= \sin{\theta_{k,n-1}}{v_{k,n}\Delta T},

 &d_{k,n}^2\!=\!d_{k,n-1}^2\!+\!(v_{k,n}\Delta T)^2\!-\!2d_{k,n-1}v_{k,n}\Delta T \cos{\theta_{k,n-1}}.
\end{align*}
The kinematic equations show that the mobility leads to changes in the angle and distance between the BS and vehicle over time slots, which motivates accurate beam prediction.
{For example, a variation in the vehicle speed changes both the distance and the angle between consecutive time slots. We note that the mobility model is used only to generate the training and test trajectories, and the kinematic equations are not embedded in the proposed network, unlike model-based trackers such as EKF \cite{liu2020radar}. Hence, the network learns the temporal evolution from the historical sensing echoes and beamformers, and can be retrained with trajectories from other mobility models, e.g., microscopic traffic simulators, without modifying its architecture.}
\subsection{Problem Formulation}
We formulate an optimization problem to maximize the sum SE while satisfying both the sensing SINR requirement and the total transmit power budget.
Then, the received sensing SINR \cite{liu2022learning,zhang2024transformer} of vehicle $k$  at the BS is defined as
\begin{align}
 &\xi_{k,n}({\bf F}_n) = \frac{|\beta_{k,n}|^2|{\bf a}^{\sf H}(\theta_{k,n}){\bf f}_{k,n}|^2}{|\beta_{k,n}|^2\sum_{j\neq k}^{K}|{\bf a}^{\sf H}(\theta_{k,n}){\bf f}_{j,n}|^2+\Psi +\sigma^2/P},
 \label{eq:radarSINR}
\end{align}
where $\Psi = \sum_{i\neq k}^{K}|\beta_{i,n}|^2|{\bf b}^{\sf H}(\theta_{k,n}){\bf b}(\theta_{i,n})|^2||{\bf a}^{\sf H}(\theta_{i,n}){\bf F}_n||^2$.
Accordingly, using \eqref{eq:Received signal} and \eqref{eq:radarSINR}, we formulate an optimization problem as follows:
\begin{align}
 \mathop{{\text{maximize}}}_{{\bf F}_{n}}& \;\;
 {\mathbb{E}}_{{\bf H}_n\!|{\bf  E}_n^{\tau},{\bf F}_n^{\tau}}\!\left[\!\sum_{k = 1}^{K}\log_2\!\left(\!\!1\!+\!\frac{\!|{\bf h}_{k,n}^{\sf H}{\bf f}_{k,n}|^2}{\sum_{i\neq k}^{K}\!|{\bf h}_{k,n}^{\sf H}{\bf f}_{i,n}|^2\!+\!\frac{\sigma^2}{P}}\!\right)\!\right]
 \label{eq:reformulated opt1}

 \mathop{{\text{subject to}}} \;\; &{{\rm Tr}}\left( {\bf F}_n{{\bf F}^{\sf H}_n}\right) \leq  1,
 \label{eq:TXpow}

 &\xi_{k,n}({\bf F}_n) \ge {\Gamma}_{k,n}\label{eq:SINR},
\end{align}
where ${\bf h}_{k,n}^{\sf H} = \sqrt{ \alpha_{k,n}}{\bf a}^{\sf H}(\theta_{k,n})$ is the channel vector between the BS and the $k$th vehicle and ${\bf H}_n = [{\bf h}_{1,n},\cdots,{\bf h}_{K,n}]$ is the corresponding channel matrix.
Here, the historical echo signals from time slot $(n-\tau)$ to time slot $(n-1)$ are denoted by ${\bf  E}_n^{\tau} = [ {\bf E}_{n-\tau},  {\bf E}_{n-\tau+1},\cdots, {\bf E}_{n-1}]$, where $ {\bf E}_{l}=[ {\bf e}_{1,l},\cdots, {\bf e}_{K,l}]^{\sf H}$ represents the echo signals from all $K$ vehicles at time slot $l$.
The historical beamformers are denoted by ${\bf F}_n^{\tau} = [{\bf F}_{n-\tau}, {\bf F}_{n-\tau+1},\cdots,{\bf F}_{n-1}]$, where ${\bf F}_{l}=[{\bf f}_{1,l},\ldots,{\bf f}_{K,l}]$ represents the beamforming matrix for  $K$ vehicles at time slot $l$.
Moreover, ${\Gamma}_{k,n}$ denotes the minimum sensing SINR threshold, \eqref{eq:TXpow} represents the transmit power constraint of the BS, and \eqref{eq:SINR} indicates the sensing SINR constraint.
